//
// Register H&E stained and multiplexed tissue images and transform segmentation masks using stainwarpy
//

include { STAINWARPY_REGISTER         } from 'nf-core/stainwarpy/register'
include { STAINWARPY_EXTRACTCHANNEL   } from 'nf-core/stainwarpy/extractchannel'
include { STAINWARPY_TRANSFORMSEGMASK } from 'nf-core/stainwarpy/transformsegmask'

workflow TIF_REGISTRATION_STAINWARPY {

    take:
    ch_hne              // channel: [ val(meta), path to .tif ]
    ch_multiplexed      // channel: [ val(meta), path to .tif ]
    ch_segmask          // channel: [ val(meta), path to .tif ] (optional)
    val_fixed_img       // val: fixed image to use ("multiplexed" or "hne")
    val_final_img_sz    // val: final image size to use ("multiplexed" or "hne")

    main:
    ch_transformed_segmask = channel.empty()
    ch_multiplexed_forward = channel.empty()

    if ( val_fixed_img == 'multiplexed') {
        STAINWARPY_EXTRACTCHANNEL ( ch_multiplexed )
        ch_multiplexed_forward = STAINWARPY_EXTRACTCHANNEL.out.single_ch_image
        STAINWARPY_REGISTER ( ch_hne, ch_multiplexed_forward,  val_fixed_img, val_final_img_sz )
    } else {
        STAINWARPY_REGISTER ( ch_hne, ch_multiplexed, val_fixed_img, val_final_img_sz )
        ch_multiplexed_forward = ch_multiplexed
    }

    if ( ch_segmask ) {
        STAINWARPY_TRANSFORMSEGMASK ( ch_hne, ch_multiplexed_forward, ch_segmask, STAINWARPY_REGISTER.out.tform_map, val_fixed_img, val_final_img_sz )
        ch_transformed_segmask = STAINWARPY_TRANSFORMSEGMASK.out.transformed_seg_mask
    }

    emit:
    transformed_image   = STAINWARPY_REGISTER.out.reg_image                     // channel: [ val(meta), *_transformed_image.ome.tif             ]
    metrics             = STAINWARPY_REGISTER.out.reg_metrics_tform             // channel: [ val(meta), *_registration_metrics_tform_map.json   ]
    transformed_segmask = ch_transformed_segmask                                // channel: [ val(meta), *_transformed_segmentation_mask.ome.tif ]
}

nextflow_workflow {

    name "Test Subworkflow TIF_REGISTRATION_STAINWARPY"
    script "../main.nf"
    workflow "TIF_REGISTRATION_STAINWARPY"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/tif_registration_stainwarpy"
    tag "stainwarpy/extractchannel"
    tag "stainwarpy/register"
    tag "stainwarpy/transformsegmask"

    test("colon_tissue_local - ome.tif - with_mask") {

        when {
            workflow {
                """
                input[0] = [
                    [ id:'sample1' ],
                    file(params.modules_testdata_base_path + 'imaging/hne_multiplexed/hne_image_colon.ome.tif', checkIfExists: true),
                ]
                input[1] = [
                    [ id:'sample1' ],
                    file(params.modules_testdata_base_path + 'imaging/hne_multiplexed/multiplexed_image_colon.ome.tif', checkIfExists: true),
                ]
                input[2] = [
                    [ id:'sample1' ],
                    file(params.modules_testdata_base_path + 'imaging/hne_multiplexed/hne_segmentation_mask.ome.tif', checkIfExists: true),
                ]
                input[3] = 'multiplexed'
                input[4] = 'multiplexed'
                """
            }
        }
        then {
            assert workflow.success
            assertAll(
                { assert snapshot(
                    file(workflow.out.transformed_image[0][1]).name,
                    file(workflow.out.transformed_segmask[0][1]).name,
                    file(workflow.out.metrics[0][1]).name
                ).match() }
            )
        }
    }

    test("colon_tissue_local - ome.tif - no_mask") {

        when {
            workflow {
                """
                input[0] = [
                    [ id:'sample1' ],
                    file(params.modules_testdata_base_path + 'imaging/hne_multiplexed/hne_image_colon.ome.tif', checkIfExists: true),
                ]
                input[1] = [
                    [ id:'sample1' ],
                    file(params.modules_testdata_base_path + 'imaging/hne_multiplexed/multiplexed_image_colon.ome.tif', checkIfExists: true),
                ]
                input[2] = []
                input[3] = 'multiplexed'
                input[4] = 'multiplexed'
                """
            }
        }
        then {
            assert workflow.success
            assertAll(
                { assert snapshot(
                    file(workflow.out.transformed_image[0][1]).name,
                    file(workflow.out.metrics[0][1]).name,
                    workflow.out.transformed_segmask
                ).match() }
            )
        }
    }

    test("colon_tissue_local - ome.tif - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = [
                    [ id:'sample1' ],
                    file(params.modules_testdata_base_path + 'imaging/hne_multiplexed/hne_image_colon.ome.tif', checkIfExists: true),
                ]
                input[1] = [
                    [ id:'sample1' ],
                    file(params.modules_testdata_base_path + 'imaging/hne_multiplexed/multiplexed_image_colon.ome.tif', checkIfExists: true),
                ]
                input[2] = [
                    [ id:'sample1' ],
                    file(params.modules_testdata_base_path + 'imaging/hne_multiplexed/hne_segmentation_mask.ome.tif', checkIfExists: true),
                ]
                input[3] = 'multiplexed'
                input[4] = 'multiplexed'
                """
            }
        }
        then {
            { assert workflow.success }
            { assert snapshot(workflow.out).match() }
        }
    }
}

